import React, { useEffect, useState } from "react";
import Navigation from "./components/Navigation";
import HomePage from "./components/HomePage";
import PropertyList from "./components/PropertyList";
import PropertyDetail from "./components/PropertyDetail";
import PropertyFilter from "./components/PropertyFilter";
import { fetchAllProperties, fetchPropertyById, filterProperties } from "./utils/api";

const App = () => {
  const [currentPage, setCurrentPage] = useState('home');
  const [properties, setProperties] = useState([]);
  const [selectedProperty, setSelectedProperty] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const loadProperties = async () => {
    setLoading(true);
    setError("");
    try {
      const data = await fetchAllProperties();
      setProperties(data);
    } catch (err) {
      setError(err.message);
    }
    setLoading(false);
  };

  useEffect(() => {
    if (currentPage === 'properties' && properties.length === 0) {
      loadProperties();
    }
  }, [currentPage, properties.length]);

  const handleSelect = async (property) => {
    setLoading(true);
    try {
      const detail = await fetchPropertyById(property.id);
      setSelectedProperty(detail);
    } catch (err) {
      setError(err.message);
    }
    setLoading(false);
  };

  const handleFilter = async (criteria) => {
    setLoading(true);
    try {
      const result = await filterProperties(criteria);
      setProperties(result);
    } catch (err) {
      setError(err.message);
    }
    setLoading(false);
  };

  const handleClear = () => {
    loadProperties();
  };

  const handleNavigate = (page) => {
    setCurrentPage(page);
    setSelectedProperty(null);
  };

  const renderContent = () => {
    if (selectedProperty) {
      return (
        <PropertyDetail
          property={selectedProperty}
          onBack={() => setSelectedProperty(null)}
        />
      );
    }

    switch (currentPage) {
      case 'home':
        return <HomePage onNavigate={handleNavigate} />;
      case 'properties':
        return (
          <div className="properties-page">
            <div className="page-header">
              <h1>Properties</h1>
              <p>Find your perfect property from our extensive collection</p>
            </div>
            <PropertyFilter
              onFilter={handleFilter}
              onClear={handleClear}
              loading={loading}
            />
            <PropertyList
              properties={properties}
              loading={loading}
              error={error}
              onSelect={handleSelect}
            />
          </div>
        );
      default:
        return <HomePage onNavigate={handleNavigate} />;
    }
  };

  return (
    <div className="app">
      <Navigation currentPage={currentPage} onNavigate={handleNavigate} />
      <main className="main-content">
        {renderContent()}
      </main>
    </div>
  );
};

export default App;
